import inspect
import matplotlib.figure as mfig
import qiskit.visualization.gate_map as gm
from qiskit.visualization import plot_gate_map, plot_histogram
from qiskit_ibm_runtime.fake_provider import FakeManilaV2

# The Graphviz BINARY is absent in this sandbox, so the leaf renderer
# plot_coupling_map is stubbed out; all argument handling above it runs for
# real and we record exactly what reaches the renderer.
_sig = inspect.signature(gm.plot_coupling_map)
_cap = {}


def _stub(*a, **kw):
    _cap.clear()
    _cap.update(_sig.bind(*a, **kw).arguments)
    return mfig.Figure()


gm.plot_coupling_map = _stub

backend = FakeManilaV2()
counts = {"00": 512, "11": 512}
links = [list(p) for p in backend.coupling_map]


def attempt(fn):
    _cap.clear()
    try:
        r = fn()
        return {"ok": True, "what": type(r).__name__, "cap": dict(_cap), "fig": r}
    except Exception as e:
        return {"ok": False, "what": type(e).__name__ + ": " + str(e)[:80], "cap": {}, "fig": None}


tries = {
    "A": ("plot_histogram(counts)", lambda: plot_histogram(counts)),
    "B": ("plot_gate_map(counts)", lambda: plot_gate_map(counts)),
    "C": ("plot_histogram(backend)", lambda: plot_histogram(backend)),
    "D": ("plot_gate_map(backend.coupling_map)", lambda: plot_gate_map(backend.coupling_map)),
    "E": ("plot_gate_map(backend.target)", lambda: plot_gate_map(backend.target)),
    "F": ("plot_gate_map(backend)", lambda: plot_gate_map(backend)),
}
evidence = {}
proven = []
observed = {"device_links": links}
hist_ticks = None
for k, (label, fn) in tries.items():
    r = attempt(fn)
    drew_map = bool(r["ok"] and [list(p) for p in (r["cap"].get("coupling_map") or [])] == links)
    observed[k] = r["what"]
    if r["ok"]:
        evidence[k] = (f"{label} -> returned a {r['what']}; did it reach the coupling-map renderer?"
                       f" {bool(r['cap'])}; were the device's qubit pairs the thing drawn? {drew_map}")
    else:
        evidence[k] = f"{label} -> {r['what']}; no connectivity diagram is produced ({drew_map})"
    if k == "A" and r["fig"] is not None:
        hist_ticks = [t.get_text() for t in r["fig"].axes[0].get_xticklabels()]
    if drew_map:
        proven.append(k)
evidence["A"] += f"  (its x axis is labelled with the outcome bitstrings {hist_ticks}, not with qubits)"
evidence["F"] += f"  (the renderer received the backend's {len(links)} directed qubit pairs {links})"
observed["histogram_xticklabels"] = hist_ticks
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
